import { REG } from './region.h.js';

export function hero_inside(r) {
    return (r.player_flags & REG.HERO_INSIDE) >>> 0;
}
export function heros_fault(r) {
    return !((r.player_flags & REG.NOT_HEROS) >>> 0) ? 1 : 0;
}
export function set_hero_inside(r) {
    return r.player_flags = (r.player_flags | REG.HERO_INSIDE) >>> 0;
}
export function clear_hero_inside(r) {
    return r.player_flags = (r.player_flags & 4294967294) >>> 0;
}
export function set_heros_fault(r) {
    return r.player_flags = (r.player_flags & 4294967293) >>> 0;
}
export function clear_heros_fault(r) {
    return r.player_flags = (r.player_flags | REG.NOT_HEROS) >>> 0;
}
